"Это DWG — закрытый формат AutoCAD, прочитать его напрямую нельзя. Откройте чертёж в AutoCAD или nanoCAD и сохраните как DXF («Сохранить как» → DXF), затем загрузите сюда":"这是 DWG — AutoCAD 的封闭格式，无法直接读取。请在 AutoCAD 或 nanoCAD 中打开图纸并另存为 DXF（「另存为」→ DXF），然后上传到这里",
"Это пример: дом {n} × {n} м. Поправьте стены на плане и посмотрите вкладки «{n}D» и «Объёмы»":"这是示例：{n} × {n} m 的房屋。请在平面图上修改墙体，并查看「{n}D」和「工程量」选项卡",
"DWG напрямую не читается: сохраните его в AutoCAD или nanoCAD как DXF. Из чертежа берутся стены, двери и окна одного этажа; армирование, узлы и инженерные сети в модель не попадают":"DWG 无法直接读取：请在 AutoCAD 或 nanoCAD 中另存为 DXF。从图纸中提取一个楼层的墙体、门和窗；配筋、节点和工程管网不会进入模型",
"«Просто наложить» — режим со слоями, прозрачностью и снимком, но без ходьбы: модель держится только при повороте телефона":"「直接叠加」— 带图层、透明度和拍摄功能的模式，但不能走动：模型仅在转动手机时保持位置",
