"Контур стен замкнут не на всех этажах: там не посчитаны помещения и перекрытие. Доведите стены до углов на плане":"并非所有楼层的墙体轮廓都已闭合：这些楼层未计算房间和楼板。请在平面图上将墙体画到角点",
"Лист А{n} с размерами, площадями помещений и штампом. Формат SVG: откройте в браузере и напечатайте или сохраните как PDF":"A{n} 图幅，含尺寸、房间面积和标题栏。SVG 格式：可在浏览器中打开并打印或另存为 PDF",
