"На iPhone и iPad здание открывается в «Быстром просмотре»: на экране — то, что видит камера, и модель в настоящую величину. Она стоит на месте: к ней можно подойти и обойти вокруг. Пальцами её можно подвинуть, повернуть и уменьшить":"在 iPhone 和 iPad 上，建筑以「快速查看」打开：屏幕上是摄像头看到的画面和实际大小的模型。它固定在原位：您可以走近并绕行。用手指可移动、旋转和缩小它",
