"На экране — то, что видит камера, и поверх него здание в настоящую величину. Оно стоит на месте: к нему можно подойти, обойти вокруг и зайти внутрь через дверные проёмы":"屏幕上是摄像头看到的画面，其上叠加实际大小的建筑。它固定在原位：您可以走近、绕行，并通过门洞走进去",
"На экране будет то, что видит камера, и поверх него — модель. Её можно подвинуть и повернуть пальцами, отключить слои и сделать снимок":"屏幕上将显示摄像头看到的画面，其上叠加模型。可用手指移动和旋转它、关闭图层并拍摄",
