", раскрытие не определено: линия тоньше {n} пикселей фото — укажите ширину участка или снимите ближе, класс может оказаться выше":"，宽度未确定：裂缝线细于照片的 {n} 个像素 — 请填写部位宽度或靠近拍摄，等级可能更高",
"Белый налёт — соли, которые выносит вода, проходящая сквозь конструкцию: признак протечки или намокания":"白色析出物 — 水穿过结构时带出的盐分：渗漏或受潮的迹象",
"Бетон откалывается от удара, промерзания во влажном состоянии или давления ржавеющей арматуры":"混凝土因撞击、潮湿状态下冻融或钢筋锈胀压力而剥落",
"Вскрыть участок, зачистить металл до чистого, обработать преобразователем ржавчины и восстановить защитный слой ремонтным составом":"凿开该部位，将金属清理干净，用除锈转化剂处理，并用修补材料恢复保护层",
"Вырезать повреждённый участок по ровному контуру, очистить, обработать битумной эмульсией и заделать асфальтобетонной смесью с уплотнением":"沿规整轮廓切除损坏部位，清理，涂刷乳化沥青，用沥青混凝土混合料填补并压实",
"Глубокий разлом / силовая трещина бетона":"混凝土深层断裂 / 受力裂缝",
"Для несущих элементов сверить размер и число сучков с сортом древесины по проекту; выпавшие сучки — заделать, ослабленный элемент — усилить или заменить":"对承重构件，应按设计的木材等级核对木节的大小和数量；脱落的木节应填补，被削弱的构件应加固或更换",
"Зачистить арматуру, оценить потерю сечения (при заметной — нужен расчёт и усиление), обработать антикоррозийным составом и восстановить защитный слой":"清理钢筋，评估截面损失（明显时需计算并加固），用防腐材料处理并恢复保护层",
"Зачистить и закрасить или зашлифовать; на металле — загрунтовать антикоррозийным составом":"清理后涂漆或打磨；金属表面需涂防腐底漆",
"Защитный слой бетона разрушен, арматура открыта влаге и воздуху и теряет сечение":"混凝土保护层已破坏，钢筋暴露于潮气和空气中，截面正在损失",
"Конструктивная трещина с раскрытием":"有开度的结构裂缝",
"Коррозия / ржавые потёки":"锈蚀 / 锈水流痕",
"Краска, штукатурка или плитка отстают от основания — обычно из-за влаги или слабого сцепления":"油漆、抹灰或瓷砖与基层脱离 — 通常由潮湿或粘结不牢引起",
"Механическое повреждение поверхности; на металле через царапину начинается коррозия":"表面机械损伤；金属会从划痕处开始锈蚀",
"Найти и устранить источник влаги, очистить поверхность, после просушки обработать гидрофобизатором":"查明并消除潮湿来源，清理表面，干燥后用憎水剂处理",
"Найти и устранить источник воды, просушить конструкцию, затем восстановить отделку":"查明并消除水源，烘干结构，然后恢复装修",
"Оценить, несущий ли элемент: несущий — показать инженеру, остальное — выправить или заменить и восстановить покрытие":"判断是否为承重构件：承重构件请交工程师查看，其余可校正或更换并恢复面层",
"Плесень растёт там, где конструкция постоянно влажная и плохо проветривается":"霉菌生长在结构长期潮湿且通风不良的地方",
"Покрытие разрушено до основания: вода, морозы и нагрузка от колёс выбивают ослабленный участок":"面层已破坏至基层：水、冻融和车轮荷载会使薄弱部位脱落",
"Ржавчина выходит на поверхность, когда корродирует арматура или закладные детали под защитным слоем":"保护层下的钢筋或预埋件锈蚀时，锈迹会渗出表面",
"Скол / разрушение бетона":"混凝土崩缺 / 破坏",
"След удара или перегрузки: на металле и пластике вмятина ослабляет элемент и повреждает покрытие":"撞击或超载的痕迹：金属和塑料上的凹陷会削弱构件并损坏面层",
"Снять отслоившийся слой до прочного, выяснить и устранить причину увлажнения, загрунтовать и восстановить отделку":"将剥离层清除至坚实处，查明并消除受潮原因，涂底漆并恢复装修",
"Сучок (порок древесины)":"木节（木材缺陷）",
"Сучок ослабляет сечение деревянного элемента; выпадающие сучки и сучки с трещиной хуже здоровых":"木节会削弱木构件的截面；脱落的木节和带裂缝的木节比健全的更差",
"Тёмное или жёлтое пятно — след воды: протекает кровля, труба или шов":"深色或黄色污渍 — 水迹：屋面、管道或接缝渗漏",
"Удалить слабый бетон до прочного, обеспылить, загрунтовать и восстановить сечение ремонтной смесью; при глубине до арматуры — сначала защитить арматуру":"将松散混凝土清除至坚实处，除尘，涂底漆并用修补砂浆恢复截面；如深及钢筋 — 先保护钢筋",
"Усадочная трещина штукатурного слоя / скол":"抹灰层收缩裂缝 / 崩缺",
"Устранить источник влаги и наладить вентиляцию, удалить поражённую отделку, обработать антисептиком и восстановить":"消除潮湿来源并改善通风，清除受侵蚀的装修层，用防腐剂处理并恢复",
