"Волосяные трещины в пределах допуска: расшить и затереть ремонтным составом при ближайшей отделке; при появлении новых трещин — поставить маяки":"允许范围内的发丝裂缝：在下次装修时开槽并用修补材料抹平；如出现新裂缝 — 安装观测标",
