"По осмотру — расценок на эти работы в базе нет":"需勘查 — 价格库中没有这些工程的单价",
"По фото не определяется":"无法根据照片确定",
"Повышенный: раскрытие больше {n} мм — влага доходит до арматуры":"偏高：宽度超过 {n} mm — 潮气可到达钢筋",
"работоспособное":"可正常使用",
"Работоспособное — нужен ремонт, чтобы влага не проникала к арматуре":"可正常使用 — 需要维修，以防潮气渗入钢筋",
"Расшивка и затирка волосяных трещин ремонтным составом":"发丝裂缝的开槽和用修补材料抹平",
"Расшивка и инъектирование трещин под давлением":"裂缝开槽和压力注浆",
"Расшить трещину и заполнить её низковязким эпоксидным составом (инъектирование), затем восстановить защитный слой ремонтной смесью, чтобы влага не попадала к арматуре":"将裂缝开槽并用低黏度环氧材料填充（注浆），然后用修补砂浆恢复保护层，以防潮气到达钢筋",
"Срочно вызвать специализированную организацию для обследования по ГОСТ {n} и выяснить причину (осадка, перегрузка, промерзание, удар). До решения — оградить место и ограничить нагрузку. Сборный элемент (кольцо колодца, плиту, перемычку) с раскрытой трещиной, как правило, заменяют или усиливают обоймой; инъектирование — только как временная мера":"请立即请专业机构按 GOST {n} 进行检测并查明原因（沉降、超载、冻融、撞击）。在作出决定前 — 围挡该处并限制荷载。带张开裂缝的预制构件（井圈、板、过梁）通常应更换或用围套加固；注浆仅作为临时措施",
"Умеренный: раскрытие больше допустимых {n} мм — со временем возможна коррозия":"中等：宽度超过允许的 {n} mm — 日久可能发生锈蚀",
"Установить маяки и {n}–{n} недели наблюдать, растёт ли раскрытие. Если трещина не растёт — расшить, инъектировать эпоксидным составом под давлением через пакеры и восстановить защитный слой. Если растёт — нужно обследование и усиление конструкции":"安装观测标并观察 {n}–{n} 周，看宽度是否增大。如裂缝不再发展 — 开槽，通过注浆嘴压力注入环氧材料并恢复保护层。如继续发展 — 需要对结构进行检测和加固",
"Установка маяков и наблюдение за раскрытием ({n}–{n} недели)":"安装观测标并监测裂缝宽度（{n}–{n} 周）",
